// MCP entry: authenticate, then establish context. Fail-closed throughout.
//
// This node does AUTHORIZATION (who is asking, for which tenant, with what
// entitlement). It deliberately does NOT decide APPROVAL -- the five
// contact-a-human tools are routed to agent/action-execute, whose Policy Gate
// owns that decision. One policy, one place.

const body = ($input.item.json && $input.item.json.body) || $input.item.json || {};
const secret = body.internal_secret || '';
const expected = $env.INTERNAL_EMAIL_SECRET || '';

function deny(error, extra) {
  return { json: Object.assign({
    valid: false, error: error, tool_name: body.tool_name || '', tool_input: body.tool_input || {}
  }, extra || {}) };
}

// 1. Authentication. An unset secret must never mean "allow".
if (!expected || secret !== expected) return deny('internal secret required');

const toolName = body.tool_name || '';
const toolInput = body.tool_input || {};

// 2. Risk class per capability. A tool absent from this table has no declared
//    risk and is refused -- adding a capability now requires classifying it.
const RISK = {
  place_outbound_call: 'CONTACT_HUMAN',
  send_whatsapp:       'CONTACT_HUMAN',
  send_sms:            'CONTACT_HUMAN',
  send_email:          'CONTACT_HUMAN',
  book_meeting:        'CONTACT_HUMAN',
  generate_video:      'WRITE_INTERNAL',
  update_lead_status:  'WRITE_INTERNAL',
  log_decision:        'WRITE_INTERNAL',
  escalate_to_human:   'WRITE_INTERNAL',
  retrieve_lead_memory:'READ',
  assess_why_now:      'READ',
  next_best_action:    'REASONING'
};

if (!toolName) return deny('tool_name required');
if (!RISK.hasOwnProperty(toolName)) {
  return deny('unknown tool: ' + toolName + '. Available: ' + Object.keys(RISK).join(', '));
}
const risk = RISK[toolName];

// 3. Tenant context is mandatory for everything that is not pure reasoning.
//    A caller-supplied client_id is a claim, not proof -- it is checked
//    against agent_personalities downstream (the executor) and against the
//    tenant's own rows for direct reads.
const client_id = toolInput.client_id || body.client_id || null;
if (!client_id) {
  return deny('client_id required: MCP will not execute without tenant context', { risk_class: risk });
}

// 4. Agent identity and correlation, so an action can be traced back to who
//    asked for it and which decision it belongs to.
const agent_id = body.agent_id || toolInput.agent_id || null;
const correlation_id = body.correlation_id || toolInput.decision_id || null;
if (!agent_id) {
  return deny('agent_id required', { risk_class: risk });
}

// 5. Product context. Capabilities belong to products; knowing a tool name
//    must not be enough to reach another product's surface.
const PRODUCT = {
  place_outbound_call: 'sales_engine', send_whatsapp: 'sales_engine',
  send_sms: 'sales_engine', send_email: 'sales_engine',
  book_meeting: 'sales_engine', generate_video: 'sales_engine',
  update_lead_status: 'sales_engine', log_decision: 'sales_engine',
  escalate_to_human: 'sales_engine', retrieve_lead_memory: 'sales_engine',
  assess_why_now: 'sales_engine',
  next_best_action: 'sales_engine'
};
const product = PRODUCT[toolName] || null;
if (!product) return deny('no product mapping for tool', { risk_class: risk });

// 6. Sensitive capabilities are not executed here. They are handed to the
//    action executor, which applies the autonomy and approval policy. This is
//    the whole point of the change: MCP cannot be the shorter path.
const ROUTED_TO_EXECUTOR = ['place_outbound_call','send_whatsapp','send_sms','send_email','book_meeting'];
const ACTION_TYPE = {
  place_outbound_call: 'voice', send_whatsapp: 'whatsapp',
  send_sms: 'sms', send_email: 'email', book_meeting: 'book'
};

return { json: {
  valid: true,
  tool_name: toolName,
  tool_input: toolInput,
  client_id: client_id,
  agent_id: agent_id,
  product: product,
  risk_class: risk,
  correlation_id: correlation_id,
  via_executor: ROUTED_TO_EXECUTOR.indexOf(toolName) !== -1,
  executor_action_type: ACTION_TYPE[toolName] || null,
  requested_at: new Date().toISOString()
} };

const ctx = $('Parse Request').item.json;
const all = $input.all();
const data = all.length === 1 ? (all[0].json && (all[0].json.result || all[0].json)) : all.map(function(i){return i.json;});
return { json: { success: true, tool: ctx.tool_name, data: data, timestamp: new Date().toISOString() } };

// Why Now -- deterministic classification over data that already exists.
//
// The point is that an error must never read as buying intent. The signal
// pipeline writes 'Unavailable' when the provider or parser failed (284 rows
// currently), and that is a different state from "we looked and found
// nothing". Collapsing the two is how a failure became a reason to call
// someone.

const ctx = $('Parse Request').item.json;
const rows = $input.all().map(function (i) { return i.json; });
const lead = (rows.length === 1 && Array.isArray(rows[0])) ? rows[0][0] : rows[0];

if (!lead || !lead.id) {
  return [{ json: { result: {
    why_now: 'UNKNOWN_ERROR',
    reason: 'lead_not_found_for_tenant',
    note: 'No lead with that id belongs to this client. Not treated as an absence of signal.',
    correlation_id: ctx.correlation_id || null
  } } }];
}

const signal = lead.detected_signal || null;
const conf = lead.signal_confidence || null;
const ERROR_CONF = ['Unavailable', 'Error', 'Failed'];
const VERIFIED_CONF = ['High', 'Medium'];

function daysSince(ts) {
  if (!ts) return null;
  const d = (Date.now() - new Date(ts).getTime()) / 86400000;
  return isFinite(d) ? Math.floor(d) : null;
}

let out;

if (conf && ERROR_CONF.indexOf(conf) >= 0) {
  // Provider or parser failure. Explicitly NOT a signal, and never urgency.
  out = {
    why_now: 'UNKNOWN_ERROR',
    reason: 'signal_detection_unavailable',
    confidence: null,
    urgency: null,
    interpretation: 'Signal detection did not complete for this lead. That is a gap in our '
                  + 'information, not evidence about the prospect.',
    safe_to_treat_as_intent: false
  };
} else if (!signal || String(signal).trim() === '') {
  out = {
    why_now: 'NO_VERIFIED_SIGNAL',
    reason: 'no_signal_detected',
    confidence: null,
    urgency: 'none',
    interpretation: 'Nothing time-sensitive is known about this lead. Any outreach rests on '
                  + 'fit alone, not timing.',
    safe_to_treat_as_intent: false
  };
} else if (VERIFIED_CONF.indexOf(conf) >= 0) {
  const age = daysSince(lead.updated_at);
  out = {
    why_now: 'VERIFIED_SIGNAL',
    signal: signal,
    evidence: lead.research_summary || lead.research_angle || null,
    source: lead.research_summary ? 'lead_research' : 'signal_detection',
    // The schema records no separate observation time for a signal, so the
    // last write is the closest honest proxy -- and is labelled as one.
    observed_at: lead.updated_at || null,
    observed_at_is_proxy: true,
    recency_days: age,
    recency: age === null ? 'unknown' : (age <= 14 ? 'fresh' : (age <= 60 ? 'ageing' : 'stale')),
    confidence: conf,
    interpretation: lead.likely_business_need
      ? ('Signal aligns with a likely need: ' + lead.likely_business_need)
      : 'Signal detected; no inferred business need recorded.',
    urgency: (age !== null && age <= 14 && conf === 'High') ? 'high'
           : (age !== null && age <= 60) ? 'medium' : 'low',
    safe_to_treat_as_intent: true
  };
} else {
  // Low confidence is not verification.
  out = {
    why_now: 'NO_VERIFIED_SIGNAL',
    reason: 'signal_below_confidence_threshold',
    signal_seen: signal,
    confidence: conf,
    urgency: 'none',
    interpretation: 'A weak signal was recorded but does not meet the bar to act on.',
    safe_to_treat_as_intent: false
  };
}

out.lead_id = lead.id;
out.client_id = lead.client_id;
out.correlation_id = ctx.correlation_id || null;
out.assessed_at = new Date().toISOString();
return [{ json: { result: out } }];

// Next Best Action -- a capability on the existing runtime, not a second agent.
//
// Deterministic on purpose. Every field can be pointed at a column; nothing
// is inferred that the data does not support. risk_class uses the same
// vocabulary as the policy gate, so the executor's answer is predictable
// from here.

const ctx = $('Parse Request').item.json;
const rows = $input.all().map(function (i) { return i.json; });
const lead = (rows.length === 1 && Array.isArray(rows[0])) ? rows[0][0] : rows[0];

if (!lead || !lead.id) {
  return [{ json: { result: {
    action: 'stop', why: 'lead_not_found_for_tenant', urgency: 'none',
    evidence: [], confidence: 1.0, risk_class: 'READ', approval_required: false,
    correlation_id: ctx.correlation_id || null
  } } }];
}

const ev = [];
const push = function (k, v) {
  if (v !== null && v !== undefined && v !== '') ev.push(k + '=' + v);
};

const researched = !!(lead.research_summary && String(lead.research_summary).trim());
const scored = lead.lead_score !== null && lead.lead_score !== undefined;
const conf = lead.signal_confidence || null;
const signalErrored = !!(conf && ['Unavailable', 'Error', 'Failed'].indexOf(conf) >= 0);
const verifiedSignal = !!(lead.detected_signal && ['High', 'Medium'].indexOf(conf) >= 0);

push('lead_status', lead.lead_status);
push('lead_score', lead.lead_score);
push('priority_level', lead.priority_level);
push('signal_confidence', conf);
push('researched', researched);

let action, why, urgency, risk, approval, confidence;

// Ordered by precedence: suppression first, then information gaps, then
// timing. A lead that must not be contacted is never reasoned past.
if (lead.unsubscribed) {
  action = 'stop';
  why = 'Lead has unsubscribed. Contact is suppressed permanently.';
  urgency = 'none'; risk = 'READ'; approval = false; confidence = 1.0;
} else if (!researched) {
  action = 'research';
  why = 'No research summary exists, so there is nothing evidence-based to say. '
      + 'Contacting now would mean inventing a reason.';
  urgency = 'medium'; risk = 'READ'; approval = false; confidence = 0.9;
} else if (!scored) {
  action = 'research';
  why = 'Research exists but the lead has not been scored, so fit is unknown.';
  urgency = 'low'; risk = 'READ'; approval = false; confidence = 0.8;
} else if (signalErrored) {
  action = 'collect_information';
  why = 'Signal detection failed for this lead. The gap is in our data, not the prospect, '
      + 'and it should be closed before any timing-based outreach.';
  urgency = 'low'; risk = 'READ'; approval = false; confidence = 0.75;
} else if (lead.last_email_sent_at || lead.outreach_sent_at) {
  action = 'follow_up';
  why = 'This lead has already been contacted and has not reached a closed state.';
  urgency = verifiedSignal ? 'medium' : 'low';
  risk = 'CONTACT_HUMAN'; approval = true; confidence = 0.7;
} else if (verifiedSignal) {
  action = 'contact';
  why = 'Researched, scored, and carrying a verified signal -- the timing is evidenced '
      + 'rather than assumed.';
  urgency = 'high'; risk = 'CONTACT_HUMAN'; approval = true; confidence = 0.85;
} else if ((lead.lead_score || 0) >= 60) {
  action = 'contact';
  why = 'Strong fit on score with no timing signal. Worth contacting on fit alone, with no '
      + 'urgency claimed.';
  urgency = 'low'; risk = 'CONTACT_HUMAN'; approval = true; confidence = 0.6;
} else {
  action = 'wait';
  why = 'Researched and scored, but neither fit nor timing justifies contact yet.';
  urgency = 'none'; risk = 'READ'; approval = false; confidence = 0.65;
}

return [{ json: { result: {
  action: action,
  why: why,
  urgency: urgency,
  evidence: ev,
  confidence: confidence,
  risk_class: risk,
  // Under recommend_only every CONTACT_HUMAN action needs a human. This is
  // advisory only: the policy gate in the Action Executor enforces it.
  approval_required: approval,
  autonomy_note: 'approval_required is advisory. The Action Executor policy gate decides.',
  lead_id: lead.id,
  client_id: lead.client_id,
  correlation_id: ctx.correlation_id || null,
  decided_at: new Date().toISOString()
} } }];
